package com.yeyamo_mobile.api.messaging_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import org.springframework.data.cassandra.core.mapping.*;import com.yeyamo_mobile.api.messaging_service.domain.ConversationType;
@Table("conversations")public class ConversationEntity{@PrimaryKey private UUID id;@Column private ConversationType type;@Column private String title;@Column("owner_id")private String ownerId;@Column("created_at")private Instant createdAt;@Column("updated_at")private Instant updatedAt;@Column("last_message_id")private UUID lastMessageId;@Column("last_message_preview")private String lastMessagePreview;@Column("last_message_at")private Instant lastMessageAt;
 public static ConversationEntity create(ConversationType type,String title,String owner){var c=new ConversationEntity();c.id=UUID.randomUUID();c.type=type;c.title=title;c.ownerId=owner;c.createdAt=Instant.now();c.updatedAt=c.createdAt;return c;}public void message(UUID id,String preview,Instant at){lastMessageId=id;lastMessagePreview=preview;lastMessageAt=at;updatedAt=at;}public void rename(String title){this.title=title;updatedAt=Instant.now();}
 public UUID getId(){return id;}public ConversationType getType(){return type;}public String getTitle(){return title;}public String getOwnerId(){return ownerId;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public UUID getLastMessageId(){return lastMessageId;}public String getLastMessagePreview(){return lastMessagePreview;}public Instant getLastMessageAt(){return lastMessageAt;}}
